import{_ as s,C as n,o as t,c,j as a,a as r,b as d,w as o,E as l,a2 as g,a3 as h}from"./chunks/framework.CHYjUC2p.js";const x=JSON.parse('{"title":"Feature Inventory & Architectural Traces (F1 - F16)","description":"","frontmatter":{},"headers":[],"relativePath":"01-features.md","filePath":"01-features.md"}'),u={name:"01-features.md"};function m(p,e,y,f,b,F){const i=n("Mermaid");return t(),c("div",null,[e[1]||(e[1]=a("h1",{id:"feature-inventory-architectural-traces-f1-f16",tabindex:"-1"},[r("Feature Inventory & Architectural Traces (F1 - F16) "),a("a",{class:"header-anchor",href:"#feature-inventory-architectural-traces-f1-f16","aria-label":'Permalink to "Feature Inventory & Architectural Traces (F1 - F16)"'},"​")],-1)),(t(),d(g,null,{default:o(()=>[l(i,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20CoreEngine%20%5BCore%20Caching%20%26%20Proxy%20Engine%5D%0A%20%20%20%20%20%20%20%20F1%5BF1%3A%20RFC%209111%20Cache%20Core%5D%0A%20%20%20%20%20%20%20%20F2%5BF2%3A%20Request%20Coalescing%5D%0A%20%20%20%20%20%20%20%20F3%5BF3%3A%20Multi-Tier%20Storage%5D%0A%20%20%20%20%20%20%20%20F4%5BF4%3A%20Eviction%20Algorithms%5D%0A%20%20%20%20%20%20%20%20F5%5BF5%3A%20Conditional%20Revalidation%5D%0A%20%20%20%20%20%20%20%20F8%5BF8%3A%20Range%20Requests%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20OptimizationSecurity%20%5BOptimization%20%26%20Security%5D%0A%20%20%20%20%20%20%20%20F6%5BF6%3A%20Surrogate%20Tag%20Purge%5D%0A%20%20%20%20%20%20%20%20F7%5BF7%3A%20Streaming%20Compression%5D%0A%20%20%20%20%20%20%20%20F9%5BF9%3A%20Multi-Origin%20Routing%5D%0A%20%20%20%20%20%20%20%20F10%5BF10%3A%20Edge%20Security%20WAF%5D%0A%20%20%20%20%20%20%20%20F14%5BF14%3A%20Ketama%20Consistent%20Hashing%5D%0A%20%20%20%20%20%20%20%20F15%5BF15%3A%20Pre-Warming%20%26%20Prefetch%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20OperationsTelemetry%20%5BTelemetry%20%26%20Control%20Plane%5D%0A%20%20%20%20%20%20%20%20F11%5BF11%3A%20Prometheus%20Observability%5D%0A%20%20%20%20%20%20%20%20F12%5BF12%3A%20Embedded%20Admin%20SPA%5D%0A%20%20%20%20%20%20%20%20F13%5BF13%3A%20Next.js%2014%20Dashboard%5D%0A%20%20%20%20%20%20%20%20F16%5BF16%3A%20AIML%20Model%20Layer%5D%0A%20%20%20%20end%0A%0A%20%20%20%20F10%20--%3E%20F1%0A%20%20%20%20F1%20--%3E%20F2%0A%20%20%20%20F2%20--%3E%20F3%0A%20%20%20%20F3%20--%3E%20F4%0A%20%20%20%20F1%20--%3E%20F5%0A%20%20%20%20F1%20--%3E%20F7%0A%20%20%20%20F1%20--%3E%20F8%0A%20%20%20%20F2%20--%3E%20F9%0A%20%20%20%20F9%20--%3E%20F14%0A%20%20%20%20F6%20--%3E%20F3%0A%20%20%20%20F1%20--%3E%20F11%0A%20%20%20%20F11%20--%3E%20F12%0A%20%20%20%20F12%20--%3E%20F13%0A%20%20%20%20F11%20-.%20Telemetry%20.-%3E%20F16%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=h('<hr><h2 id="feature-master-index" tabindex="-1">Feature Master Index <a class="header-anchor" href="#feature-master-index" aria-label="Permalink to &quot;Feature Master Index&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:left;">Feature Name</th><th style="text-align:left;">Core Files</th><th style="text-align:left;">Category</th><th style="text-align:left;">User-Facing Behavior</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./features/F1-rfc9111-cache-core.html">F1</a></strong></td><td style="text-align:left;">RFC 9111 Cache Core</td><td style="text-align:left;"><code>src/cache/lookup.ts</code>, <code>serve.ts</code></td><td style="text-align:left;">Core</td><td style="text-align:left;">Sub-millisecond cache lookups with <code>X-Cache: HIT/MISS</code> headers.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F2-request-collapsing.html">F2</a></strong></td><td style="text-align:left;">Request Coalescing</td><td style="text-align:left;"><code>src/proxy/coalesce.ts</code>, <code>forward.ts</code></td><td style="text-align:left;">Concurrency</td><td style="text-align:left;">Collapses 500 simultaneous misses to 1 upstream fetch.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F3-multi-tier-storage.html">F3</a></strong></td><td style="text-align:left;">Multi-Tier Storage</td><td style="text-align:left;"><code>src/cache/memory-store.ts</code>, <code>disk-store.ts</code></td><td style="text-align:left;">Storage</td><td style="text-align:left;">In-memory RAM cache backed by disk files with compaction.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F4-eviction-algorithms.html">F4</a></strong></td><td style="text-align:left;">Eviction Algorithms</td><td style="text-align:left;"><code>src/cache/eviction/lru.ts</code>, <code>lfu.ts</code></td><td style="text-align:left;">Storage</td><td style="text-align:left;">LRU/LFU/SLRU/TTL eviction bounded by memory limits and quotas.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F5-conditional-revalidation.html">F5</a></strong></td><td style="text-align:left;">Conditional Revalidation</td><td style="text-align:left;"><code>src/cache/revalidate.ts</code>, <code>refresh.ts</code></td><td style="text-align:left;">Caching</td><td style="text-align:left;">Synchronous and background 304 revalidation using ETags.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F6-surrogate-key-purge.html">F6</a></strong></td><td style="text-align:left;">Surrogate-Key Tag Purge</td><td style="text-align:left;"><code>src/purge/api.ts</code>, <code>audit.ts</code></td><td style="text-align:left;">Invalidation</td><td style="text-align:left;">Sub-5ms tag purge backed by a SHA-256 tamper-evident log.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F7-streaming-compression.html">F7</a></strong></td><td style="text-align:left;">Streaming Compression</td><td style="text-align:left;"><code>src/compression/codecs.ts</code></td><td style="text-align:left;">Optimization</td><td style="text-align:left;">On-the-fly Brotli, Gzip, and Zstandard compression.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F8-byte-range-requests.html">F8</a></strong></td><td style="text-align:left;">Byte-Range Partial Content</td><td style="text-align:left;"><code>src/range/parse-range.ts</code></td><td style="text-align:left;">Streaming</td><td style="text-align:left;">RFC 7233 206 Partial Content for video streaming and seeking.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F9-multi-origin-health.html">F9</a></strong></td><td style="text-align:left;">Multi-Origin Routing</td><td style="text-align:left;"><code>src/config/origins.ts</code>, <code>health/</code></td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Weighted load balancing with active probes and circuit breakers.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F10-edge-security-waf.html">F10</a></strong></td><td style="text-align:left;">Edge Security WAF &amp; TLS</td><td style="text-align:left;"><code>src/security/ip.ts</code>, <code>jwt.ts</code></td><td style="text-align:left;">Security</td><td style="text-align:left;">CIDR IP filtering, Host verification, JWT auth, and SNI TLS.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F11-observability-metrics.html">F11</a></strong></td><td style="text-align:left;">Observability &amp; Metrics</td><td style="text-align:left;"><code>src/observability/metrics.ts</code></td><td style="text-align:left;">Telemetry</td><td style="text-align:left;">Prometheus 0.0.4 metrics exposition and OpenTelemetry tracing.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F12-admin-control-plane.html">F12</a></strong></td><td style="text-align:left;">Embedded Admin SPA</td><td style="text-align:left;"><code>src/admin/server.ts</code>, <code>dashboard-html.ts</code></td><td style="text-align:left;">Control Plane</td><td style="text-align:left;">Built-in zero-dependency operational control panel on port 9090.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F13-nextjs-telemetry-dashboard.html">F13</a></strong></td><td style="text-align:left;">Next.js 14 Dashboard</td><td style="text-align:left;"><code>frontend/app/dashboard/page.tsx</code></td><td style="text-align:left;">UI</td><td style="text-align:left;">Full-screen React 18 / Next.js dashboard with live Recharts curves.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F14-consistent-hashing-cluster.html">F14</a></strong></td><td style="text-align:left;">Ketama Hash Cluster</td><td style="text-align:left;"><code>src/cluster/consistent-hashing.ts</code></td><td style="text-align:left;">Scalability</td><td style="text-align:left;">Deterministic hash ring with virtual nodes and peer proxy routing.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F15-cache-prewarming.html">F15</a></strong></td><td style="text-align:left;">Cache Pre-Warming</td><td style="text-align:left;"><code>src/warm/warm-prefetch.ts</code></td><td style="text-align:left;">Optimization</td><td style="text-align:left;">Proactive background URL warming and preload header prefetcher.</td></tr><tr><td style="text-align:left;"><strong><a href="./features/F16-aiml-tier-models.html">F16</a></strong></td><td style="text-align:left;">AIML Tier Models</td><td style="text-align:left;"><code>aiml/MODEL_CARD.md</code></td><td style="text-align:left;">AIML</td><td style="text-align:left;">Tier A cache popularity prediction &amp; Tier B forensic LLM diagnostics.</td></tr></tbody></table><hr><h2 id="detailed-feature-trace-summaries" tabindex="-1">Detailed Feature Trace Summaries <a class="header-anchor" href="#detailed-feature-trace-summaries" aria-label="Permalink to &quot;Detailed Feature Trace Summaries&quot;">​</a></h2><h3 id="f1-rfc-9111-caching-core-header-parsing" tabindex="-1">F1: RFC 9111 Caching Core &amp; Header Parsing <a class="header-anchor" href="#f1-rfc-9111-caching-core-header-parsing" aria-label="Permalink to &quot;F1: RFC 9111 Caching Core &amp; Header Parsing&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: <code>GET /static/bundle.js</code> issued by browser client.</li><li><strong>Proxy Flow</strong>: <code>src/proxy/index.ts:180</code> calls <code>parseRequest</code>, generates canonical cache key via <code>generateCacheKey</code> in <code>src/cache/key.ts</code>. <code>lookupCache</code> in <code>src/cache/lookup.ts</code> queries <code>MemoryStore</code>.</li><li><strong>On Cache HIT</strong>: <code>serveCacheHit</code> in <code>src/cache/serve.ts</code> sets <code>X-Cache: HIT</code>, calculates <code>Age</code> via <code>freshness.ts</code>, and pipes buffer directly to <code>res</code>.</li><li><strong>On Cache MISS</strong>: Proxies upstream via <code>forward.ts</code>, pipes response into client while <code>CacheTeeStream</code> in <code>src/cache/fill.ts</code> saves it into <code>MemoryStore</code>.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I built the RFC 9111 caching engine in <code>src/cache/lookup.ts</code> and <code>src/cache/serve.ts</code> to provide strict HTTP-compliant caching at sub-millisecond edge speeds. When a request arrives, the proxy normalizes the query parameters and headers into a canonical SHA-256 key and checks our memory store. On a cache hit, we evaluate the object&#39;s age and freshness lifetime, attach <code>X-Cache: HIT</code> and <code>Age</code> headers, and stream the cached buffer straight to the client socket without touching disk or origin. If the object has expired, we check for <code>stale-while-revalidate</code> directives; if present, we serve the stale content immediately to keep user latency under one millisecond while kicking off a background revalidation to origin. The main alternative was a naive memory dictionary, but implementing full RFC 9111 semantics ensures compliance with standard browser and CDN behaviors.&quot;</p></blockquote><h3 id="f2-single-flight-request-coalescing-thundering-herd" tabindex="-1">F2: Single-Flight Request Coalescing (Thundering Herd) <a class="header-anchor" href="#f2-single-flight-request-coalescing-thundering-herd" aria-label="Permalink to &quot;F2: Single-Flight Request Coalescing (Thundering Herd)&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: 500 concurrent requests for uncached URL <code>/flash-sale/banner.webp</code>.</li><li><strong>Flow</strong>: Each request invokes <code>RequestCoalescer.joinOrLead()</code> in <code>src/proxy/coalesce.ts</code>. The first request creates a flight in <code>flightMap</code> and is elected leader. The other 499 requests register their resolve callbacks into <code>InflightWaiter</code> and pause without initiating sockets.</li><li><strong>Resolution</strong>: When the leader receives the origin response stream, <code>resolveWaiters()</code> broadcasts the stream chunks simultaneously to all 499 waiting client responses and writes one copy to cache.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I engineered request coalescing in <code>src/proxy/coalesce.ts</code> to protect origin web servers and databases from catastrophic thundering herd cache stampedes. When hundreds of concurrent requests miss the cache for the exact same resource simultaneously, dispatching all of them to the origin would saturate database connection pools and crash the backend. Instead, my <code>joinOrLead</code> algorithm designates the first arriving request as the leader and suspends the subsequent 499 requests in an in-memory waiter map. The leader issues a single upstream HTTP request. When the response stream arrives, we fan out the chunks to all 500 client sockets simultaneously and commit one copy into the cache. This reduced our upstream traffic during stampedes by 99.8% while keeping memory usage strictly bounded.&quot;</p></blockquote><h3 id="f3-multi-tier-memory-segmented-disk-storage" tabindex="-1">F3: Multi-Tier Memory &amp; Segmented Disk Storage <a class="header-anchor" href="#f3-multi-tier-memory-segmented-disk-storage" aria-label="Permalink to &quot;F3: Multi-Tier Memory &amp; Segmented Disk Storage&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Cached object storage and retrieval.</li><li><strong>Flow</strong>: Objects under 5 MB are stored in <code>MemoryStore</code> (<code>src/cache/memory-store.ts</code>). Objects exceeding memory quotas are written into <code>DiskStore</code> (<code>src/cache/disk-store.ts</code>) across segment files with a persistent index in <code>src/cache/metadata-index.ts</code>.</li><li><strong>Compaction</strong>: Background compaction in <code>src/cache/compaction.ts</code> reclaims deleted and overwritten segment space safely using reference counting.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I designed a multi-tier storage engine in <code>src/cache/memory-store.ts</code> and <code>src/cache/disk-store.ts</code> that combines sub-millisecond RAM lookups with large-capacity persistent SSD caching. Small, frequently requested static assets are cached directly in Node.js Buffers inside <code>MemoryStore</code>, bounded by strict tenant quotas to prevent any single tenant from monopolizing the cache. For larger assets and persistent retention across proxy restarts, the proxy spills to <code>DiskStore</code>, storing data in segmented files with an in-memory metadata index. When disk space becomes fragmented after object updates and evictions, our background compaction worker reclaims dead bytes without interrupting active reads.&quot;</p></blockquote><h3 id="f4-eviction-algorithms-lru-lfu-slru-ttl" tabindex="-1">F4: Eviction Algorithms (LRU, LFU, SLRU, TTL) <a class="header-anchor" href="#f4-eviction-algorithms-lru-lfu-slru-ttl" aria-label="Permalink to &quot;F4: Eviction Algorithms (LRU, LFU, SLRU, TTL)&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Memory utilization reaches <code>maxTotalBytes</code> limit.</li><li><strong>Flow</strong>: <code>MemoryStore.store()</code> detects capacity overflow and triggers <code>evictNext()</code> from the active policy in <code>src/cache/eviction/</code>.</li><li><strong>Policies</strong>: LRU uses a doubly-linked list (<code>src/cache/eviction/lru.ts</code>), LFU uses frequency buckets (<code>src/cache/eviction/lfu.ts</code>), and SLRU separates probationary and protected tiers (<code>src/cache/eviction/slru.ts</code>).</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I implemented four distinct cache eviction algorithms in <code>src/cache/eviction/</code>—LRU, LFU, Segmented LRU, and TTL—so the proxy can adapt its memory eviction strategy to different traffic patterns. In default LRU mode, we maintain a doubly-linked list tracking item access recency in O(1) time. For workloads subject to one-hit-wonder scans that would flush popular items out of a naive LRU, I added Segmented LRU, which requires an item to be accessed twice before promoting it to the protected segment. When capacity thresholds are breached, the policy evicts low-priority entries and emits telemetry metrics to Prometheus to track eviction rates.&quot;</p></blockquote><h3 id="f5-conditional-revalidation-304-handling" tabindex="-1">F5: Conditional Revalidation &amp; 304 Handling <a class="header-anchor" href="#f5-conditional-revalidation-304-handling" aria-label="Permalink to &quot;F5: Conditional Revalidation &amp; 304 Handling&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Client or proxy revalidating an expired or conditional cache entry.</li><li><strong>Flow</strong>: <code>src/cache/preconditions.ts</code> evaluates client <code>If-None-Match</code> and <code>If-Modified-Since</code>. <code>src/cache/upstream-conditionals.ts</code> constructs upstream headers. On upstream 304 Not Modified, <code>src/cache/refresh.ts</code> updates <code>CacheEntry</code> timestamps without redownloading body bytes.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I built the conditional revalidation engine in <code>src/cache/revalidate.ts</code> and <code>src/cache/refresh.ts</code> to minimize network bandwidth during cache refreshes. When a cached object reaches its TTL, we don&#39;t discard it immediately; instead, we send an upstream conditional request carrying the cached <code>ETag</code> in an <code>If-None-Match</code> header. If the origin returns a 304 Not Modified, we refresh the object&#39;s TTL and headers in-place without re-transmitting the response body, saving 99% of bandwidth. Similarly, when clients send conditional requests to the proxy, we validate their validators against our cached metadata and return a 304 directly from the edge.&quot;</p></blockquote><h3 id="f6-surrogate-key-tag-purge-cryptographic-audit" tabindex="-1">F6: Surrogate-Key Tag Purge &amp; Cryptographic Audit <a class="header-anchor" href="#f6-surrogate-key-tag-purge-cryptographic-audit" aria-label="Permalink to &quot;F6: Surrogate-Key Tag Purge &amp; Cryptographic Audit&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Admin issues <code>POST /admin/api/v1/purge</code> with <code>{ tag: &quot;catalog-sale&quot; }</code>.</li><li><strong>Flow</strong>: <code>PurgeApiHandler</code> validates token scopes (<code>src/purge/api.ts</code>). <code>PurgeIndex</code> (<code>src/purge/index-store.ts</code>) queries inverted tag map and deletes all matching keys. <code>PurgeAuditTrail</code> (<code>src/purge/audit.ts</code>) appends a SHA-256 hash-chained audit record.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I developed the Surrogate-Key tag purge engine in <code>src/purge/</code> to enable instant, precise cache invalidation across thousands of related URLs. In e-commerce platforms, updating a single product requires invalidating category pages, search results, and promotional banners. By having origins attach <code>Surrogate-Key</code> or <code>Cache-Tag</code> headers, our proxy indexes every cache entry by its tags in an inverted index. When an invalidation API call arrives, we invalidate all matching entries in under five milliseconds. Every purge operation is cryptographically signed and appended to a SHA-256 tamper-evident audit trail, giving infrastructure teams full accountability and security compliance.&quot;</p></blockquote><h3 id="f7-streaming-compression-brotli-gzip-zstandard" tabindex="-1">F7: Streaming Compression (Brotli, Gzip, Zstandard) <a class="header-anchor" href="#f7-streaming-compression-brotli-gzip-zstandard" aria-label="Permalink to &quot;F7: Streaming Compression (Brotli, Gzip, Zstandard)&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Client requests compressible asset with <code>Accept-Encoding: gzip, br, zstd</code>.</li><li><strong>Flow</strong>: <code>src/compression/negotiate.ts</code> selects optimal codec. <code>src/compression/codecs.ts</code> transforms stream using Node.js native zlib. <code>DecompressionBombLimiter</code> enforces safety caps.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I implemented on-the-fly streaming compression in <code>src/compression/codecs.ts</code> supporting Brotli, Gzip, and Zstandard. When an upstream origin returns uncompressed text, HTML, or JSON, our proxy inspects the client&#39;s <code>Accept-Encoding</code> header, selects the highest-efficiency algorithm, and pipes the response through a native compression transform stream. To prevent malicious decompression bomb attacks from exhausting server memory, I added a custom <code>DecompressionBombLimiter</code> transform stream that aborts the transfer if decompressed bytes exceed safety thresholds.&quot;</p></blockquote><h3 id="f8-rfc-7233-byte-range-requests-video-slicing" tabindex="-1">F8: RFC 7233 Byte-Range Requests &amp; Video Slicing <a class="header-anchor" href="#f8-rfc-7233-byte-range-requests-video-slicing" aria-label="Permalink to &quot;F8: RFC 7233 Byte-Range Requests &amp; Video Slicing&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Video player sends <code>Range: bytes=1048576-2097151</code>.</li><li><strong>Flow</strong>: <code>src/range/parse-range.ts</code> validates syntax and byte boundaries. Slices cached stream buffer and returns <code>206 Partial Content</code> with <code>Content-Range: bytes 1048576-2097151/10485760</code>.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I built RFC 7233 byte-range request handling in <code>src/range/parse-range.ts</code> to power seamless media streaming and resume capabilities. When media players request video chunks or seek through an MP4, they send <code>Range</code> headers requesting specific byte offsets. The proxy parses these ranges, validates them against the total content length, slices the cached buffer using zero-copy slice operations, and returns a 206 Partial Content response with correct <code>Content-Range</code> headers. This prevents re-downloading entire video files and allows smooth video scrubbing.&quot;</p></blockquote><h3 id="f9-multi-origin-routing-active-health-probes-circuit-breaker" tabindex="-1">F9: Multi-Origin Routing, Active Health Probes &amp; Circuit Breaker <a class="header-anchor" href="#f9-multi-origin-routing-active-health-probes-circuit-breaker" aria-label="Permalink to &quot;F9: Multi-Origin Routing, Active Health Probes &amp; Circuit Breaker&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Upstream request forwarding.</li><li><strong>Flow</strong>: <code>src/config/origins.ts</code> selects target origin using weighted round-robin. <code>src/health/active.ts</code> runs periodic HTTP probes. On consecutive 5xx errors, <code>src/health/circuit-breaker.ts</code> trips to Open and diverts traffic to backup origins.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I created a resilient multi-origin load balancing and health routing system in <code>src/config/origins.ts</code> and <code>src/health/circuit-breaker.ts</code>. The proxy distributes cache misses across origin pools using weighted round-robin while a background worker sends active HTTP health probes every five seconds. If an origin server begins returning 500 errors or socket timeouts, its three-state circuit breaker trips to Open, instantly isolating the failing node and failing over to designated backup origins. When the origin recovers, the breaker enters a Half-Open state to test traffic before restoring full traffic flow.&quot;</p></blockquote><h3 id="f10-edge-security-waf-jwt-dynamic-tls-termination" tabindex="-1">F10: Edge Security WAF, JWT &amp; Dynamic TLS Termination <a class="header-anchor" href="#f10-edge-security-waf-jwt-dynamic-tls-termination" aria-label="Permalink to &quot;F10: Edge Security WAF, JWT &amp; Dynamic TLS Termination&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Ingress TCP connection and HTTP request.</li><li><strong>Flow</strong>: <code>src/tls/cert-watcher.ts</code> terminates TLS using SNI contexts. <code>src/security/ip.ts</code> filters IP against CIDR blocks. <code>src/security/host.ts</code> enforces allowed Host headers. <code>src/security/jwt.ts</code> validates token signatures and claims.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I built an edge security WAF layer in <code>src/security/</code> and <code>src/tls/</code> to protect backend origins from unauthorized access and malicious traffic. At the TLS layer, we support dynamic SNI certificate termination with hot-reload watchers that update certificates without restarting the proxy. At the HTTP layer, every request passes through CIDR-based IP allowlists and denylists, Host header spoofing checks, and JWT/OIDC authentication verification. Furthermore, our origin URL validator enforces strict SSRF protection to block attackers from routing requests to internal cloud metadata endpoints.&quot;</p></blockquote><h3 id="f11-observability-prometheus-opentelemetry" tabindex="-1">F11: Observability: Prometheus &amp; OpenTelemetry <a class="header-anchor" href="#f11-observability-prometheus-opentelemetry" aria-label="Permalink to &quot;F11: Observability: Prometheus &amp; OpenTelemetry&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Scrape <code>GET /metrics</code> or trace request.</li><li><strong>Flow</strong>: <code>MetricsRegistry</code> in <code>src/observability/metrics.ts</code> maintains atomic counters, gauges, and latency histograms. Emits Prometheus text 0.0.4. <code>src/observability/tracing.ts</code> propagates W3C <code>traceparent</code> headers.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I designed the observability architecture in <code>src/observability/metrics.ts</code> and <code>src/observability/tracing.ts</code> to provide deep visibility into edge cache performance. The proxy exposes standard Prometheus metrics at <code>/metrics</code>, tracking edge hit ratio, byte hit ratio, origin latency percentiles, and eviction counts with low-cardinality labels. For distributed tracing, our tracer generates and propagates W3C <code>traceparent</code> headers, creating nested spans for cache lookup, upstream fetch, and compression so engineers can pinpoint latency bottlenecks across microservices.&quot;</p></blockquote><h3 id="f12-admin-control-plane-embedded-spa" tabindex="-1">F12: Admin Control Plane &amp; Embedded SPA <a class="header-anchor" href="#f12-admin-control-plane-embedded-spa" aria-label="Permalink to &quot;F12: Admin Control Plane &amp; Embedded SPA&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Operator accesses <code>http://localhost:9090/admin</code>.</li><li><strong>Flow</strong>: <code>src/admin/server.ts</code> serves zero-dependency SPA rendered from <code>src/admin/dashboard-html.ts</code> with Content Security Policy nonces. Exposes authenticated REST endpoints for routes, policies, and origins.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I created a standalone administrative control plane in <code>src/admin/server.ts</code> running on port 9090. To ensure the admin dashboard is always accessible even during external CDN or NPM outages, I built an embedded single-page application with zero external CDN dependencies, protected by strict CSP nonces. Through this interface and its REST API, site reliability engineers can inspect real-time cache hit ratios, dynamically update origin routing rules, modify cache TTL policies, and manually drain unhealthy origins for maintenance.&quot;</p></blockquote><h3 id="f13-next-js-14-real-time-telemetry-dashboard" tabindex="-1">F13: Next.js 14 Real-Time Telemetry Dashboard <a class="header-anchor" href="#f13-next-js-14-real-time-telemetry-dashboard" aria-label="Permalink to &quot;F13: Next.js 14 Real-Time Telemetry Dashboard&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: User opens <code>http://localhost:3000/dashboard</code>.</li><li><strong>Flow</strong>: <code>frontend/app/dashboard/page.tsx</code> connects to port 9090, polls time-series telemetry every 1 second, and renders interactive Recharts line and area charts for hit ratio, bytes, and latencies.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I built a modern operations dashboard in <code>frontend/app/dashboard/page.tsx</code> using Next.js 14, React 18, and Recharts. The dashboard polls the admin telemetry API every second and renders live time-series charts displaying cache hit ratio, byte savings, origin latency p50/p95/p99 histograms, and memory-versus-disk storage utilization. It provides interactive forms to execute instantaneous URL and tag purges, view the real-time request decision ring buffer, and toggle origin maintenance draining with immediate UI updates.&quot;</p></blockquote><h3 id="f14-ketama-consistent-hash-ring-peer-proxy-mesh" tabindex="-1">F14: Ketama Consistent Hash Ring &amp; Peer Proxy Mesh <a class="header-anchor" href="#f14-ketama-consistent-hash-ring-peer-proxy-mesh" aria-label="Permalink to &quot;F14: Ketama Consistent Hash Ring &amp; Peer Proxy Mesh&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Multi-node horizontal scaling.</li><li><strong>Flow</strong>: <code>src/cluster/consistent-hashing.ts</code> maps canonical keys onto a 32-bit Ketama hash ring with 160 virtual nodes per server. <code>src/cluster/peer-cluster.ts</code> routes requests to the responsible peer with hop-count loop protection headers.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;To scale our caching tier horizontally across multiple servers without multiplying upstream load, I built a consistent hashing cluster mesh in <code>src/cluster/consistent-hashing.ts</code> using the Ketama algorithm. Each proxy node maps to 160 virtual points on a 32-bit ring. When a request arrives, the proxy hashes the cache key to determine which peer node owns the entry; if owned by another peer, it forwards the request internally with a loop-prevention header. This ensures that adding or removing a cache node moves only 1/Nth of the cached keys, preserving high hit ratios.&quot;</p></blockquote><h3 id="f15-cache-pre-warming-link-header-prefetcher" tabindex="-1">F15: Cache Pre-Warming &amp; Link Header Prefetcher <a class="header-anchor" href="#f15-cache-pre-warming-link-header-prefetcher" aria-label="Permalink to &quot;F15: Cache Pre-Warming &amp; Link Header Prefetcher&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Scheduled warm job or origin <code>Link: &lt;/style.css&gt;; rel=preload</code>.</li><li><strong>Flow</strong>: <code>src/warm/warm-prefetch.ts</code> parses <code>Link</code> headers on origin responses and queues prefetch requests with concurrency bounds and SSRF validation.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;I built an automated cache pre-warming and prefetch engine in <code>src/warm/warm-prefetch.ts</code>. When an origin server responds with standard HTTP <code>Link</code> headers containing <code>rel=preload</code> or <code>rel=prefetch</code>, our proxy extracts those URLs and schedules them in a background prefetch queue. The prefetcher crawls the assets during idle cycles with strict concurrency limits and SSRF destination validation, ensuring that critical CSS, JavaScript, and fonts are already warm in edge memory before clients request them.&quot;</p></blockquote><h3 id="f16-aiml-model-layer-tier-a-tier-b-intelligence" tabindex="-1">F16: AIML Model Layer (Tier A &amp; Tier B Intelligence) <a class="header-anchor" href="#f16-aiml-model-layer-tier-a-tier-b-intelligence" aria-label="Permalink to &quot;F16: AIML Model Layer (Tier A &amp; Tier B Intelligence)&quot;">​</a></h3><ul><li><strong>Starting Point</strong>: Telemetry analysis and predictive prefetching.</li><li><strong>Flow</strong>: Tier A model predicts item popularity to optimize prefetch and eviction vs naive LRU (<code>aiml/MODEL_CARD.md</code>). Tier B LLM assistant provides natural language cache-miss forensic diagnostics with strict schema validation.</li><li><strong>Say It Out Loud</strong>:</li></ul><blockquote><p>&quot;In <code>aiml/</code>, I specified a tiered AI architecture to augment CDN efficiency. Tier A is a popularity predictor model evaluated against a non-AI baseline to proactively prefetch trending content and guide eviction decisions beyond standard LRU recency. Tier B is an LLM forensic diagnostic assistant that analyzes request decision logs and header configurations to suggest caching optimizations. Crucially, in accordance with resilient systems engineering, the AI models are strictly advisory: the LLM is never on the critical latency or correctness path, and the proxy always defaults to deterministic RFC 9111 rules.&quot;</p></blockquote>',53))])}const q=s(u,[["render",m]]);export{x as __pageData,q as default};
